<script setup>
import { computed,ref,watch } from 'vue'
const props=defineProps({items:{type:Array,default:()=>[]}})
const selected=ref(0)
watch(()=>props.items,items=>{selected.value=Math.max(0,items.length-1)},{immediate:true})
const current=computed(()=>props.items[selected.value])
const max=computed(()=>Math.max(4,Math.ceil(Math.max(0,...props.items.map(v=>v.answered))/2)*2))
const x=i=>36+(i+.5)*530/Math.max(1,props.items.length)
const y=(v,limit)=>134-v/limit*104
const accuracy=v=>v==null?'暂无作答':`${v.toFixed(1)}%`
function move(e){if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();selected.value=e.key==='Home'?0:e.key==='End'?props.items.length-1:Math.max(0,Math.min(props.items.length-1,selected.value+(e.key==='ArrowRight'?1:-1)))}
</script>
<template><section class="pc-card pc-chart" data-chart="trend"><h2>作答趋势</h2><p class="muted small">每天提交的非空作答。次数与正确率分别使用独立坐标。</p><label class="pc-chart-select">查看日期<select v-model.number="selected"><option v-for="(day,i) in items" :key="day.date" :value="i">{{ day.date }}</option></select></label><div class="pc-trend-plot" tabindex="0" role="group" aria-label="每日作答趋势，左右键选择日期" @keydown="move"><p class="pc-chart-unit">作答次数（次）</p><svg viewBox="0 0 580 156" role="img" aria-label="每日作答次数柱状图"><template v-for="tick in [0,max/2,max]" :key="tick"><line x1="36" x2="570" :y1="y(tick,max)" :y2="y(tick,max)" class="pc-grid-line"/><text x="29" :y="y(tick,max)+4" text-anchor="end">{{ Math.round(tick) }}</text></template><g v-for="(day,i) in items" :key="day.date" @mouseenter="selected=i" @click="selected=i"><rect :x="x(i)-250/items.length" :y="y(day.answered,max)" :width="Math.max(2,500/items.length)" :height="Math.max(1,day.answered/max*104)" :class="['pc-bar',{'pc-bar-selected':i===selected}]"/><rect :x="x(i)-265/items.length" y="20" :width="530/items.length" height="116" fill="transparent"><title>{{ day.date }}：{{ day.answered }} 次</title></rect></g><text x="36" y="153">{{ items[0]?.date?.slice(5) }}</text><text x="568" y="153" text-anchor="end">{{ items.at(-1)?.date?.slice(5) }}</text></svg><p class="pc-chart-unit">正确率（%）· 无作答日留空</p><svg viewBox="0 0 580 156" role="img" aria-label="每日正确率点图，无作答日留空"><template v-for="tick in [0,50,100]" :key="tick"><line x1="36" x2="570" :y1="y(tick,100)" :y2="y(tick,100)" class="pc-grid-line"/><text x="29" :y="y(tick,100)+4" text-anchor="end">{{ tick }}</text></template><g v-for="(day,i) in items" :key="day.date" @mouseenter="selected=i" @click="selected=i"><line v-if="i>0&&day.accuracy!=null&&items[i-1].accuracy!=null" :x1="x(i-1)" :y1="y(items[i-1].accuracy,100)" :x2="x(i)" :y2="y(day.accuracy,100)" class="pc-line"/><circle v-if="day.accuracy!=null" :cx="x(i)" :cy="y(day.accuracy,100)" :r="i===selected?5:3" class="pc-point"/><rect :x="x(i)-265/items.length" y="20" :width="530/items.length" height="116" fill="transparent"><title>{{ day.date }}：{{ accuracy(day.accuracy) }}</title></rect></g><text x="36" y="153">{{ items[0]?.date?.slice(5) }}</text><text x="568" y="153" text-anchor="end">{{ items.at(-1)?.date?.slice(5) }}</text></svg></div><p v-if="current" class="pc-chart-value" role="status">{{ current.date }} · {{ current.answered }} 次作答 · {{ accuracy(current.accuracy) }} · {{ (current.duration_ms/60000).toFixed(1) }} 分钟</p><p v-if="!items.some(v=>v.answered)" class="muted">还没有期间作答，完成一份练习后会显示趋势。<RouterLink to="/questions">开始练习</RouterLink></p><details class="pc-table-details"><summary>查看趋势数据表</summary><div class="pc-table-scroll"><table><caption>每天的非空作答与会话记录时长</caption><thead><tr><th>日期</th><th>作答次数</th><th>正确率</th><th>分钟</th></tr></thead><tbody><tr v-for="day in items" :key="day.date"><td>{{ day.date }}</td><td>{{ day.answered }}</td><td>{{ accuracy(day.accuracy) }}</td><td>{{ (day.duration_ms/60000).toFixed(1) }}</td></tr></tbody></table></div></details></section></template>
